/* AppMypage01Mapper.countMyPresets */
SELECT COUNT(*)
  FROM TB_APRV_LINE_PRESET P
 WHERE P.CMPNY_CD = #{cmpnyCd}
   AND P.USER_CD  = #{userCd}
   AND P.USE_YN   = 'Y'

/* AppMypage01Mapper.countOtherUserByMblHmac */
SELECT COUNT(*)
  FROM TB_USER A
 WHERE A.CMPNY_CD    = #{cmpnyCd}
   AND A.MBL_NO_HMAC = #{mblNoHmac}
   AND A.USER_CD    != #{userCd}

mapper.update:
/* AppMypage01Mapper.updateProfileBasic */
UPDATE TB_USER
   SET USER_NM     = #{userNm}
     , GENDER      = #{genderCode}

     , BIRTH_DT_ENC = #{birthEnc}


     , EMAIL_ENC    = #{emailEnc}
     , EMAIL_HMAC   = #{emailHmac}
     , EMAIL_DOMAIN = #{emailDomain}

     , UPDATE_NO   = #{updateNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD  = #{userCd}

/* AppMypage01Mapper.updateProfileMobile */
UPDATE TB_USER
   SET MBL_NO_ENC   = #{mblNoEnc}
     , MBL_NO_HMAC  = #{mblNoHmac}
     , MBL_NO_LAST4 = #{mblNoLast4}
     , UPDATE_NO    = #{updateNo}
     , UPDATE_DATE  = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD  = #{userCd}

mapper.insert:
/* AppMypage01Mapper.insertSmsAuthCode */
INSERT INTO TB_SMS_AUTH_CODE (
      MBL_NO_ENC
    , MBL_NO_HMAC
    , AUTH_CD
    , EXPIRED_AT
) VALUES (
      #{mblNoEnc}
    , #{mblNoHmac}
    , #{authCode}
    , DATE_ADD(NOW(), INTERVAL 3 MINUTE)
)

mapper.select:
/* AppMypage01Mapper.selectValidSmsId */
SELECT SMS_ID
  FROM TB_SMS_AUTH_CODE
 WHERE MBL_NO_HMAC = #{mblNoHmac}
   AND AUTH_CD     = #{authCode}
   AND EXPIRED_AT  >=  NOW()
   AND VERIFIED_YN = 'N'
 ORDER BY SMS_ID DESC
 LIMIT 1

/* AppMypage01Mapper.countUnverifiedByMblHmac */
SELECT COUNT(*)
  FROM TB_SMS_AUTH_CODE
 WHERE MBL_NO_HMAC = #{mblNoHmac}
   AND EXPIRED_AT  >=  NOW()
   AND VERIFIED_YN = 'N'

mapper.update:
/* AppMypage01Mapper.markSmsVerified */
UPDATE TB_SMS_AUTH_CODE
   SET VERIFIED_YN = 'Y'
     , UPDATE_NO   = 'SYSTEM'
     , UPDATE_DATE = NOW()
 WHERE SMS_ID      = #{smsId}
   AND MBL_NO_HMAC = #{mblNoHmac}
   AND AUTH_CD     = #{authCode}
   AND EXPIRED_AT  >=  NOW()
   AND VERIFIED_YN = 'N'

mapper.select:
/* AppMypage01Mapper.selectUserPw */
SELECT A.USER_PW
  FROM TB_USER A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.USER_CD  = #{userCd}

mapper.update:
/* AppMypage01Mapper.updateUserPw */
UPDATE TB_USER
   SET USER_PW       = #{userPw}
     , PWD_CHG_DTIME = NOW()
     , UPDATE_NO     = #{userCd}
     , UPDATE_DATE   = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD  = #{userCd}

mapper.select:
/* AppMypage01Mapper.selectPresetMasters */
SELECT
      P.PRESET_ID   AS presetId
    , P.PRESET_NM   AS presetNm
    , P.DEFAULT_YN  AS defaultYn
  FROM TB_APRV_LINE_PRESET P
 WHERE P.CMPNY_CD = #{cmpnyCd}
   AND P.USER_CD  = #{userCd}
   AND P.USE_YN   = 'Y'
 ORDER BY (P.DEFAULT_YN = 'Y') DESC, P.PRESET_NM ASC, P.PRESET_ID ASC

/* AppMypage01Mapper.selectPresetById */
SELECT
      P.PRESET_ID   AS presetId
    , P.PRESET_NM   AS presetNm
    , P.DEFAULT_YN  AS defaultYn
  FROM TB_APRV_LINE_PRESET P
 WHERE P.CMPNY_CD  = #{cmpnyCd}
   AND P.USER_CD   = #{userCd}
   AND P.PRESET_ID = #{presetId}
   AND P.USE_YN    = 'Y'
 LIMIT 1

/* AppMypage01Mapper.selectPresetOwner */
SELECT P.USER_CD
  FROM TB_APRV_LINE_PRESET P
 WHERE P.CMPNY_CD  = #{cmpnyCd}
   AND P.PRESET_ID = #{presetId}
   AND P.USE_YN    = 'Y'
 LIMIT 1

/* AppMypage01Mapper.countPresetNameDup */
SELECT COUNT(*)
  FROM TB_APRV_LINE_PRESET P
 WHERE P.CMPNY_CD = #{cmpnyCd}
   AND P.USER_CD  = #{userCd}
   AND P.PRESET_NM = #{presetNm}
   AND P.USE_YN   = 'Y'

   AND P.PRESET_ID != #{excludePresetId}

/* AppMypage01Mapper.selectNextPresetId */
SELECT CONCAT('P', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'APRV_PRESET_ID'))
  FROM DUAL

/* AppMypage01Mapper.countActiveCandidate */
SELECT COUNT(*)
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.SITE_CD  = #{siteCd}
   AND U.USER_CD  = #{userCd}
   AND U.USE_YN   = 'Y'
   AND U.WITHDRAWAL_DATE IS NULL
   AND U.ACCOUNT_STATUS  = '01'
   AND U.AUTH_CD != 'system'

