/* AppMypage01Mapper.insertPresetMaster */
INSERT INTO TB_APRV_LINE_PRESET (
      CMPNY_CD, PRESET_ID, USER_CD, PRESET_NM, DEFAULT_YN, USE_YN, INSERT_NO, INSERT_DATE
) VALUES (
      #{cmpnyCd}, #{presetId}, #{userCd}, #{presetNm}, #{defaultYn}, 'Y', #{insertNo}, NOW()
)

mapper.update:
/* AppMypage01Mapper.updatePresetMaster */
UPDATE TB_APRV_LINE_PRESET
   SET PRESET_NM   = #{presetNm}
     , DEFAULT_YN  = #{defaultYn}
     , UPDATE_NO   = #{updateNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD  = #{cmpnyCd}
   AND PRESET_ID = #{presetId}

mapper.insert:
/* AppMypage01Mapper.insertPresetStep */
INSERT INTO TB_APRV_LINE_PRESET_D (
      CMPNY_CD, PRESET_ID, STEP_NO, APPROVER_USER_CD, INSERT_NO, INSERT_DATE
) VALUES (
      #{cmpnyCd}, #{presetId}, #{stepNo}, #{approverUserCd}, #{insertNo}, NOW()
)

mapper.delete:
/* AppMypage01Mapper.deletePresetSteps */
DELETE FROM TB_APRV_LINE_PRESET_D
 WHERE CMPNY_CD  = #{cmpnyCd}
   AND PRESET_ID = #{presetId}

/* AppMypage01Mapper.deletePresetMaster */
DELETE FROM TB_APRV_LINE_PRESET
 WHERE CMPNY_CD  = #{cmpnyCd}
   AND PRESET_ID = #{presetId}

mapper.update:
/* AppMypage01Mapper.clearDefaultForUser */
UPDATE TB_APRV_LINE_PRESET
   SET DEFAULT_YN = 'N'
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD  = #{userCd}
   AND DEFAULT_YN = 'Y'

/* AppMypage01Mapper.setDefault */
UPDATE TB_APRV_LINE_PRESET
   SET DEFAULT_YN  = 'Y'
     , UPDATE_NO   = #{updateNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD  = #{cmpnyCd}
   AND PRESET_ID = #{presetId}

mapper.select:
/* AppMypage01Mapper.selectApprovalCandidates */ SELECT U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , U.RANK_CD AS rankCd , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'BAIM_VAL', U.RANK_CD, 'COM007') AS rankNm , D.SORT_IDX AS rankSortIdx , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'NODE', U.SITE_CD, U.NODE_CD) AS nodeNm FROM TB_USER U LEFT JOIN TB_BAIM_VAL_D D ON D.CMPNY_CD = U.CMPNY_CD AND D.BAIM_VAL_CD = 'COM007' AND D.BAIM_VAL_D_CD = U.RANK_CD AND D.USE_YN = 'Y' WHERE U.CMPNY_CD = #{cmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL AND U.ACCOUNT_STATUS = '01' AND U.USER_CD != #{excludeUserCd} AND U.AUTH_CD != 'system'
AND U.NODE_CD = #{nodeCd}
AND U.USER_NM LIKE CONCAT('%', #{userNm}, '%')
ORDER BY (D.SORT_IDX IS NULL), D.SORT_IDX ASC, U.USER_NM ASC
